async Task VerifyCaseFileScopedKeysAsync()
{
    var keys = await ScalarLongAsync(db, """
        SELECT COUNT(*) FROM (
          SELECT TABLE_NAME, INDEX_NAME,
                 GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX SEPARATOR ',') AS cols
          FROM INFORMATION_SCHEMA.STATISTICS
          WHERE TABLE_SCHEMA = DATABASE() AND INDEX_NAME = 'PRIMARY'
            AND TABLE_NAME IN ('V5CaseFileOwnerships','V5CaseFileVersions')
          GROUP BY TABLE_NAME, INDEX_NAME
          HAVING MIN(NON_UNIQUE) = 0
        ) k
        WHERE (TABLE_NAME = 'V5CaseFileOwnerships' AND cols = 'EmpresaId,Id')
           OR (TABLE_NAME = 'V5CaseFileVersions' AND cols = 'EmpresaId,ExpedienteId,Version');
        """);
    var foreignKeys = await ScalarLongAsync(db, """
        SELECT COUNT(*) FROM (
          SELECT k.TABLE_NAME, k.CONSTRAINT_NAME, k.REFERENCED_TABLE_NAME,
                 GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION SEPARATOR ',') AS cols,
                 GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION SEPARATOR ',') AS refs
          FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE k
          JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r
            ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA
           AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME
          WHERE k.TABLE_SCHEMA = DATABASE()
            AND k.REFERENCED_TABLE_SCHEMA = DATABASE()
            AND r.DELETE_RULE IN ('RESTRICT', 'NO ACTION')
            AND k.TABLE_NAME IN ('V5CaseFileOwnerships','V5CaseFileVersions')
          GROUP BY k.TABLE_NAME, k.CONSTRAINT_NAME, k.REFERENCED_TABLE_NAME
        ) f
        WHERE (TABLE_NAME = 'V5CaseFileOwnerships' AND REFERENCED_TABLE_NAME = 'Empresas' AND cols = 'EmpresaId' AND refs = 'Id')
           OR (TABLE_NAME = 'V5CaseFileOwnerships' AND REFERENCED_TABLE_NAME = 'Sucursales' AND cols = 'SucursalId' AND refs = 'Id')
           OR (TABLE_NAME = 'V5CaseFileOwnerships' AND CONSTRAINT_NAME = 'FK_V5CaseFileOwnerships_SucursalTenant'
               AND REFERENCED_TABLE_NAME = 'Sucursales' AND cols = 'EmpresaId,SucursalId' AND refs = 'EmpresaId,Id')
           OR (TABLE_NAME = 'V5CaseFileVersions' AND REFERENCED_TABLE_NAME = 'V5CaseFileOwnerships'
               AND cols = 'EmpresaId,ExpedienteId' AND refs = 'EmpresaId,Id')
           OR (TABLE_NAME = 'V5CaseFileVersions' AND REFERENCED_TABLE_NAME = 'Usuarios' AND cols = 'ActorId' AND refs = 'Id');
        """);
    if (keys != 2 || foreignKeys != 5)
        throw new InvalidOperationException("CASEFILE_PHYSICAL_KEYS_INCOMPLETE");
}

